from datetime import datetime
from taf.cloud.lcmaas.services.auth.auth_v1 import AUTHv1
from taf.cloud.lcmaas.services.dpp.dpp_v1 import DPPv1
from taf.cloud.lcmaas.services.vi.vis_v1 import VIsv1
from taf.internal.cloud.lcmaas.client.lcmaas.v1 import Configuration, ApiClient
from taf.cloud.lcmaas.services.auth.auth_v1 import TokenProvider
from taf.cloud.lcmaas.schemas.dpps.dpp_info import DppInfoV1
from taf.cloud.lcmaas.services.neat.neat_v1 import NeatV1
from taf.cloud.lcmaas.services.cnf_pkg.cnf_pkg_v1 import CnfPackageV1
from taf.cloud.lcmaas.services.certs.certs_v1 import CertsV1
from taf.cloud.lcmaas.services.actions.actions_v1 import ActionsV1
from taf.cloud.lcmaas.schemas.vis.vi_info import VIInfoV1
from taf.cloud.lcmaas.schemas.neats.neat_info import NeatInfoV1
from taf.cloud.lcmaas.schemas.certs.cert_info_v1 import CertInfoV1
from taf.cloud.lcmaas.schemas.cnf_pkg.cnf_pkg_info_v1 import CnfPkgInfoV1


class LCMaaSv1(object):
    def __init__(self, conn_details):
        self.conn_details = conn_details
        self.conf = Configuration()
        self.conf.verify_ssl = False
        self.conf.host = conn_details.make_configuration_host(original_endpoint=self.conf.host)
        self.api_client = ApiClient(configuration=self.conf)

        self.auth = AUTHv1(api_client=self.api_client)
        self.jwt_token = self.auth.login(username=conn_details.username,
                                         password=conn_details.password)

        self.jwt_token_create_time = datetime.now()

        self.dpp = DPPv1(api_client=self.api_client)
        self.vi = VIsv1(api_client=self.api_client)
        self.neat = NeatV1(api_client=self.api_client)
        self.cnf_pkg = CnfPackageV1(api_client=self.api_client)
        self.cert = CertsV1(api_client=self.api_client)
        self.actions = ActionsV1(api_client=self.api_client)

    @TokenProvider.provide_access_token
    def get_dpps(self, group=None):
        dpps_info = self.dpp.get_dpps(group=group)
        return list(map(DppInfoV1.from_object_dict, dpps_info))

    @TokenProvider.provide_access_token
    def get_dpp_by_name(self, dpp_name):
        dpp_info = self.dpp.get_dpp_by_name(dpp_name=dpp_name)
        return DppInfoV1.from_object_dict(dpp_info)

    @TokenProvider.provide_access_token
    def update_dpp(self, dpp_name, cnfpkg_name=None, chart_override_mapping=None):
        res = self.dpp.update_dpp(dpp_name=dpp_name,
                                  cnfpkg_name=cnfpkg_name,
                                  chart_override_mapping=chart_override_mapping)
        return DppInfoV1.from_object_dict(res)

    @TokenProvider.provide_access_token
    def create_dpp(self, dpp_name, cnf_pkg_name, cnf_instance_name, vi_name, namespace,
                   chart_override_mapping=None, dpp_group=None):
        res = self.dpp.create_dpp(dpp_name=dpp_name,
                                  cnf_pkg_name=cnf_pkg_name,
                                  cnf_instance_name=cnf_instance_name,
                                  vi_name=vi_name,
                                  namespace=namespace,
                                  chart_override_mapping=chart_override_mapping,
                                  dpp_group=dpp_group)
        return DppInfoV1.from_object_dict(res)

    @TokenProvider.provide_access_token
    def delete_dpp(self, dpp_name):
        return self.dpp.delete_dpp(dpp_name=dpp_name)

    @TokenProvider.provide_access_token
    def get_vis(self, neat_name=None):
        vis_info = self.vi.get_vis(neat_name=neat_name)
        return list(map(VIInfoV1.from_object_dict, vis_info))

    @TokenProvider.provide_access_token
    def create_neat(self, name, mgmt_url, auth_url, username, password, client_id, ca_certs=None):
        res = self.neat.create_neat(name=name,
                                    mgmt_url=mgmt_url,
                                    auth_url=auth_url,
                                    username=username,
                                    password=password,
                                    client_id=client_id,
                                    ca_certs=ca_certs)
        return NeatInfoV1.from_object_dict(res)

    @TokenProvider.provide_access_token
    def get_neat_info_by_name(self, neat_name):
        return NeatInfoV1.from_object_dict(self.neat.get_neat_info_by_name(neat_name=neat_name))

    @TokenProvider.provide_access_token
    def get_neats_info(self):
        neats_info = self.neat.get_neats_info()
        return list(map(NeatInfoV1.from_object_dict, neats_info))

    @TokenProvider.provide_access_token
    def update_vi(self, vi_name, image_registry_addr=None, image_registry_user=None, image_registry_pwd=None,
                  image_registry_ca_certs=None, kubeconfig=None):
        res = self.vi.update_vi(vi_name=vi_name,
                                image_registry_addr=image_registry_addr,
                                image_registry_user=image_registry_user,
                                image_registry_pwd=image_registry_pwd,
                                image_registry_ca_certs=image_registry_ca_certs,
                                kubeconfig=kubeconfig)
        return VIInfoV1.from_object_dict(res)

    @TokenProvider.provide_access_token
    def delete_vi(self, vi_name):
        return self.vi.delete_vi(vi_name=vi_name)

    @TokenProvider.provide_access_token
    def install_certs(self, peer_type, peer_name, cert_content):
        res = self.cert.install_certs(peer_type=peer_type, peer_name=peer_name, cert_content=cert_content)
        return list(map(CertInfoV1.from_object_dict, res))

    @TokenProvider.provide_access_token
    def create_cnf_package(self, cnf_pkg_name, cnf_pkg_url):
        res = self.cnf_pkg.create_cnf_package(cnf_pkg_name=cnf_pkg_name, cnf_pkg_url=cnf_pkg_url)
        return CnfPkgInfoV1.from_object_dict(res)

    @TokenProvider.provide_access_token
    def get_cnf_package_info_by_name(self, cnf_pkg_name):
        return CnfPkgInfoV1.from_object_dict(self.cnf_pkg.get_cnf_package_info_by_name(cnf_pkg_name=cnf_pkg_name))

    @TokenProvider.provide_access_token
    def get_cnf_packages_info(self):
        return list(map(CnfPkgInfoV1.from_object_dict, self.cnf_pkg.get_cnf_packages_info()))

    @TokenProvider.provide_access_token
    def validate_dpp(self, dpp_name=None, dpp_group=None):
        return self.actions.validate_dpp(dpp_name=dpp_name, dpp_group=dpp_group)

    @TokenProvider.provide_access_token
    def onboard_container_images_to_vi(self, dpp_name=None, dpp_group=None):
        return self.actions.onboard_container_images_to_vi(dpp_name=dpp_name, dpp_group=dpp_group)

    @TokenProvider.provide_access_token
    def instantiate_dpp(self, dpp_name=None, dpp_group=None):
        return self.actions.instantiate_dpp(dpp_name=dpp_name, dpp_group=dpp_group)

    @TokenProvider.provide_access_token
    def terminate_dpp(self, dpp_name=None, dpp_group=None):
        return self.actions.terminate_dpp(dpp_name=dpp_name, dpp_group=dpp_group)

    @TokenProvider.provide_access_token
    def delete_cnf_pkg(self, cnf_pkg_name):
        return self.cnf_pkg.delete_cnf_pkg(cnf_pkg_name=cnf_pkg_name)

    @TokenProvider.provide_access_token
    def upgrade_dpp(self, dpp_name=None, dpp_group=None):
        return self.actions.upgrade_dpp(dpp_name=dpp_name, dpp_group=dpp_group)

    @TokenProvider.provide_access_token
    def rollback_dpp(self, dpp_name=None, dpp_group=None):
        return self.actions.rollback_dpp(dpp_name=dpp_name, dpp_group=dpp_group)

    @TokenProvider.provide_access_token
    def create_vi(self, vi_name, kube_config, image_registry_addr, image_registry_user, image_registry_pwd,
                  image_registry_ca_certs=None):
        res = self.vi.create_vi(vi_name=vi_name, kube_config=kube_config,
                                image_registry_addr=image_registry_addr,
                                image_registry_user=image_registry_user,
                                image_registry_pwd=image_registry_pwd,
                                image_registry_ca_certs=image_registry_ca_certs)
        return VIInfoV1.from_object_dict(res)
